"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[61],{16541:e=>{e.exports=JSON.parse('{"functions":[{"name":"sortingBy","desc":"Returns a comparator that orders two values by comparing their extracted\\nkeys pairwise: the first unequal key decides. Every call of `extract`\\nmust return the same number of keys, and mixing types at the same\\nposition will error inside `table.sort`.\\n\\n```lua\\ntable.sort(items, sortingBy(function(item)\\n\\treturn { item.category, item.price }\\nend))\\n```","params":[{"name":"extract","desc":"Maps a value to its sort keys, most significant first.","lua_type":"(T) -> { number | string }"}],"returns":[{"desc":"Comparator for `table.sort`.","lua_type":"(T, T) -> boolean"}],"function_type":"static","source":{"line":29,"path":"plugin/sorting-by/init.luau"}}],"properties":[],"types":[],"name":"sortingBy","desc":"Builds `table.sort` comparators from a key-extraction function, so\\nmulti-level sorts read declaratively instead of as nested ifs.","source":{"line":10,"path":"plugin/sorting-by/init.luau"}}')}}]);